---RefreshView 刷新界面
---@param questId integer @ 关卡id
---@param taskInfo table @ 任务完成信息
function GachaCoinQuestChallengeTasksInfo:RefreshView(questId, taskInfo)

    local questType = GCQUtils.GetGachaCoinQuestTypeById(questId)
    local isChallengeQuest = GCQConstants.Defines.QuestType.Challenge == questType
    if not isChallengeQuest then
        -- 不是挑战模式 直接隐藏任务板
        KTool.SetActive(self.controller, false)
        return
    else
        -- 刷新挑战模式任务信息
        KTool.SetActive(self.controller, true)
        self:RefreshTasksInfo(questId, taskInfo)
    end
end

---RefreshTasksInfo 刷新任务信息
---@param questId integer @ 关卡id
---@param taskInfo table @ 任务完成信息
function GachaCoinQuestChallengeTasksInfo:RefreshTasksInfo(questId, taskInfo)
    -- hide all --
    -- hide all --
    local tasks = GCQUtils.GetChallengeTasksByQuestId(questId)
    if nil ~= tasks and nil ~= next(tasks) then
        local progress = 0
        for index, taskId in ipairs(tasks) do
            if GCQConstants.Defines.TaskState.Complete == taskInfo[tostring((taskId))] then
                progress = progress + 1
            end
            -- 刷新一个任务节点
            self:RefreshOneTask(
                index,
                checkInt(questId), checkInt(taskId), taskInfo[tostring(taskId)] or GCQConstants.Defines.TaskState.Default
            )
        end
        self.TitleLabel.text = localize(string.format("任务目标<size=22>（%s/3）</size>",progress))
    end
end

---RefreshOneTask 刷新一个任务
---@param index integer @ 序号
---@param questId integer @ 关卡id
---@param taskId integer @ 任务id
---@param taskState GachaCoinQuestConstants.Defines.TaskState 任务状态
function GachaCoinQuestChallengeTasksInfo:RefreshOneTask(index, questId, taskId, taskState)
    local cell = self:GetCellByIndex(index)
    if not IsNull(cell) then
        KTool.SetActive(cell.gameObject, true)
        local cellScript = GetLuaBehaviour(cell.gameObject, GCQConstants.Path.ChallengeTaskCellScript)
        if not IsNull(cellScript) then
            cellScript.Env:RefreshView(questId, taskId, taskState)
        end
    end
end

