---@param index integer @ 序号
---@return UnityEngine.RectTransform @ ChallengeTaskInfo 任务cell
function GachaCoinQuestChallengeTasksInfo:GetCellByIndex(index)
    local cellPrefab = self.cells[index]
    if IsNull(cellPrefab) then
        cellPrefab = self:NewOneTaskInfo(index)
    end
